function norm(v){return String(v||'').trim();}
let override='';
try { const w=$('Public Listening Webhook').first().json||{}; override=norm(w.body?.district_id||w.district_id); } catch(e) {}
const by=new Map();
for(const item of $input.all()){
 const j=item.json||{}; if(!j.district_id) continue;
 const d=by.get(j.district_id)||{district_id:j.district_id,district_name:norm(j.district_name)||String(j.district_id).replace(/-/g,' '),query_ids:[],positive_terms:[]};
 d.query_ids.push(j.id); const q=norm(j.query_text);
 const rx=/(^|[^-])"([^"]{5,100})"/g; let m;
 while((m=rx.exec(q))!==null){ const t=norm(m[2]); if(t&&!d.positive_terms.some(x=>x.toLowerCase()===t.toLowerCase())) d.positive_terms.push(t); }
 by.set(j.district_id,d);
}
let rows=[...by.values()].map(d=>{d.positive_terms=[d.district_name,...d.positive_terms].filter((x,i,a)=>x&&a.findIndex(y=>y.toLowerCase()===x.toLowerCase())===i).slice(0,18);d.search_query=d.district_name;return d;});
if(override) rows=rows.filter(x=>x.district_id===override);
if(!rows.length) throw new Error(override?'social_query_override_not_found':'no_active_social_queries');
return rows.map(json=>({json}));
